//go:build amd64

package floats

import "math"

// AVX2 kernels of the float64 Log and of the correctly rounded float32 Exp and
// Log, generated by go-asmgen (explog_amd64_gen.go) into explog_amd64.s. They
// were written for go-ndarray (#94 float32 exp/log, #96 float64 log) and moved
// here as K1 of the go-scikit performance campaign. Every kernel runs the Go
// transcription's operations in its order (expCR fuses exactly where cr_expf
// does, logCR and Log keep every product unfused), so the SIMD blocks and the Go
// blocks agree bit for bit; a block holding a lane the kernel does not finish is
// not stored, it is handed back to Go.
//
// They need AVX2 and FMA (the gate of the other kernels, hasAVX2FMA).

// expCRConsts is the constant block exp32CRAVX2 reads (explog_amd64_gen.go,
// exp32CRKernel): each constant as a 4-lane vector at the offset the kernel
// uses, then the clamp bounds as 8 floats, then the 64 table mantissas.
type expCRConsts struct {
	shift, invLn2, ln2Hi, ln2Lo [4]float64 // offsets 0, 32, 64, 96
	c0, c1, c2, c3              [4]float64 // 128, 160, 192, 224
	idxMask, expMask            [4]uint64  // 256, 288
	lo, hi                      [8]float32 // 320, 352
	table                       [64]uint64 // 384
}

var expCRK = func() *expCRConsts {
	k := new(expCRConsts)
	for i := range 4 {
		k.shift[i], k.invLn2[i], k.ln2Hi[i], k.ln2Lo[i] = crShift, crInvLn2, crLn2Hi, crLn2Lo
		k.c0[i], k.c1[i], k.c2[i], k.c3[i] = crC0, crC1, crC2, crC3
		k.idxMask[i], k.expMask[i] = 63, 0xfff0000000000000
	}
	for i := range 8 {
		k.lo[i], k.hi[i] = -512, 512
	}
	k.table = crMant
	return k
}()

// useExp32AVX2 selects the AVX2 kernel; a var so tests can force the Go path.
var useExp32AVX2 = hasAVX2FMA

// exp32Fast is the correctly rounded float32 exp: blocks of 8 on the AVX2
// kernel, the rest (and every element without AVX2+FMA) on exp32CR. Both
// compute expCR's operations in the same order, so they agree bit for bit.
func exp32Fast(dst, src []float32) {
	src = src[:len(dst)]
	n := 0
	if useExp32AVX2 {
		n = len(dst) &^ 7
		if n > 0 {
			exp32CRAVX2(&dst[0], &src[0], n, expCRK)
		}
	}
	exp32CR(dst[n:], src[n:])
}

//go:noescape
func exp32CRAVX2(dst, src *float32, n int, k *expCRConsts)

// logCRConsts is the constant block log32CRAVX2 reads (explog_amd64_gen.go,
// log32CRKernel), at the offsets the kernel uses.
type logCRConsts struct {
	one, ln2, b0, b1, b2, w               [4]float64  // offsets 0, 32, 64, 96, 128, 160
	sub, maxv, mmask, jadd, bias, oneBits [8]uint32   // 192, 224, 256, 288, 320, 352
	expOr                                 [4]uint64   // 384
	tr, tl                                [65]float64 // 416, 936
}

var logCRK = func() *logCRConsts {
	k := new(logCRConsts)
	for i := range 4 {
		k.one[i], k.ln2[i], k.w[i] = 1, 0x1.62e42fefa39efp-1, 0x1.f06p-33
		k.b0[i], k.b1[i], k.b2[i] = logCRB[0], logCRB[1], logCRB[2]
		k.expOr[i] = 1023 << 23
	}
	for i := range 8 {
		// The kernel's positive-normal test: ux + sub (wrapping) <= maxv as int32.
		k.sub[i], k.maxv[i], k.mmask[i] = 0x7f800000, 0xfeffffff, 1<<23-1
		k.jadd[i], k.bias[i], k.oneBits[i] = 1<<16, 127, 0x3f800000
	}
	k.tr, k.tl = logCRTr, logCRTl
	return k
}()

// useLog32AVX2 selects the AVX2 kernel; a var so tests can force the Go path.
var useLog32AVX2 = hasAVX2FMA

// log32Fast is the correctly rounded float32 log: blocks of 8 on the AVX2
// kernel, which hands back each block it cannot finish (an input that is not
// a positive normal float32, or bounds that round apart, about 1 lane in
// 2800) to logCR, as is the tail. Both run logCR's operations in its order,
// so they agree bit for bit.
func log32Fast(dst, src []float32) {
	src = src[:len(dst)]
	i := 0
	if useLog32AVX2 {
		n := len(dst) &^ 7
		for i < n {
			i += log32CRAVX2(&dst[i], &src[i], n-i, logCRK)
			if i < n {
				logCRSlice(dst[i:i+8], src[i:i+8])
				i += 8
			}
		}
	}
	logCRSlice(dst[i:], src[i:])
}

//go:noescape
func log32CRAVX2(dst, src *float32, n int, k *logCRConsts) (done int)

// logConsts is the constant block logAVX2 reads (explog_amd64_gen.go,
// logKernel), each value as a 4-lane vector at the offset the kernel uses.
type logConsts struct {
	lo, hiMax, n1loM1, n1hi [4]uint64  // offsets 0, 32, 64, 96
	off, idxMask, topMask   [4]uint64  // 128, 160, 192
	magic                   [4]uint64  // 224
	magicSub                [4]float64 // 256
	x2048                   [4]uint64  // 288
	negOne, ln2hi, ln2lo    [4]float64 // 320, 352, 384
	a0, a1, a2, a3, a4      [4]float64 // 416, 448, 480, 512, 544
}

var logK = func() *logConsts {
	k := new(logConsts)
	for i := range 4 {
		k.lo[i], k.hiMax[i] = 0x0010<<48, 0x7fefffffffffffff
		k.n1loM1[i] = math.Float64bits(1.0-0x1p-4) - 1
		k.n1hi[i] = math.Float64bits(1.0 + 0x1.09p-4)
		k.off[i], k.idxMask[i], k.topMask[i] = logOff, logN-1, 0xfff<<52
		k.magic[i], k.magicSub[i], k.x2048[i] = 0x4330000000000000, 0x1p52+2048, 0x800
		k.negOne[i], k.ln2hi[i], k.ln2lo[i] = -1, logLn2hi, logLn2lo
		k.a0[i], k.a1[i], k.a2[i], k.a3[i], k.a4[i] = logA0, logA1, logA2, logA3, logA4
	}
	return k
}()

// useLogAVX2 selects the AVX2 kernel; a var so tests can force the Go path.
var useLogAVX2 = hasAVX2FMA

// logFast runs blocks of 4 on the AVX2 kernel, which hands back each block
// holding an input Log does not take through its table path (not a positive
// normal, or within 2^-4 of 1) to logScalar, as is the tail. Both run the
// same operations in the same order, so they agree bit for bit.
func logFast(dst, src []float64) {
	i := 0
	if useLogAVX2 {
		n := len(src) &^ 3
		for i < n {
			i += logAVX2(&dst[i], &src[i], n-i, logK, &logTab[0])
			if i < n {
				logScalar(dst[i:i+4], src[i:i+4])
				i += 4
			}
		}
	}
	logScalar(dst[i:], src[i:])
}

//go:noescape
func logAVX2(dst, src *float64, n int, k *logConsts, tab *logEntry) (done int)
